// Regenerates src/lib/brand-icon.ts from assets/brand-icon.png (the connector's
// logo, 512x512). Embedded as base64 so the hosted image ships it with no extra
// files: `node scripts/embed-brand-icon.mjs` after replacing the PNG.
import { readFileSync, writeFileSync } from 'node:fs';
const png = readFileSync(new URL('../assets/brand-icon.png', import.meta.url));
writeFileSync(new URL('../src/lib/brand-icon.ts', import.meta.url),
  '// GENERATED by scripts/embed-brand-icon.mjs from assets/brand-icon.png. Do not edit.\n' +
  '/** The FlurryPORT logo (512x512 PNG) the hosted connector serves and advertises. */\n' +
  `export const BRAND_ICON_PNG = Buffer.from('${png.toString('base64')}', 'base64');\n` +
  "export const BRAND_ICON_MIME = 'image/png';\n" +
  "export const BRAND_ICON_SIZES = ['512x512'];\n");
